        url_database = os.path.join(directory, "configured.db")
        old_url = os.environ.get("DATABASE_URL")
        old_path = os.environ.get("DATABASE_PATH")
        try:
            os.environ["DATABASE_URL"] = url_database
            os.environ["DATABASE_PATH"] = os.path.join(directory, "fallback.db")
            code, stdout, stderr = cli_runner("init")
            assert code == 0
            assert stdout == ""
            assert stderr == ""
            assert os.path.exists(url_database)
            assert not os.path.exists(os.environ["DATABASE_PATH"])
        finally:
            if old_url is None:
                os.environ.pop("DATABASE_URL", None)
            else:
                os.environ["DATABASE_URL"] = old_url
            if old_path is None:
                os.environ.pop("DATABASE_PATH", None)
            else:
                os.environ["DATABASE_PATH"] = old_path


def test_database_missing_tables_is_operational_failure_without_output():
    with tempfile.TemporaryDirectory() as directory:
        database_path = os.path.join(directory, "empty.db")
        old_url = os.environ.get("DATABASE_URL")
        old_path = os.environ.get("DATABASE_PATH")
        try:
            os.environ["DATABASE_URL"] = database_path
            os.environ.pop("DATABASE_PATH", None)
            code, stdout, stderr = cli_runner("count")
            assert code == 1
            assert stdout == ""
            assert stderr != ""
        finally:
            if old_url is None:
                os.environ.pop("DATABASE_URL", None)
            else:
                os.environ["DATABASE_URL"] = old_url
            if old_path is None:
                os.environ.pop("DATABASE_PATH", None)
            else:
                os.environ["DATABASE_PATH"] = old_path
from importlib import import_module
import inspect


def test_cli_and_persistence_packages_are_importable():
    cli = import_module("cli")
    persistence = import_module("persistence")
    assert hasattr(cli, "main")
    assert hasattr(persistence, "open_database")


def test_cli_main_accepts_argv_and_reports_missing_command():
    from cli import main

    assert "argv" in inspect.signature(main).parameters
    assert main([]) == 2


def test_configuration_precedence():
    from configuration import database_dsn

    assert database_dsn({}) == "data/app.db"
    assert database_dsn({"DATABASE_PATH": "path.db"}) == "path.db"
    assert database_dsn({"DATABASE_URL": "url", "DATABASE_PATH": "path.db"}) == "url"


def test_validation_keeps_money_as_integer_cents():
